56	template <typename ValueType>
57	size_t
58	FindLongestCommandWord(std::map<std::string, ValueType, std::less<>> &dict) {
59	  auto end = dict.end();
60	  size_t max_len = 0;
61	
62	  for (auto pos = dict.begin(); pos != end; ++pos) {
63	    size_t len = pos->first.size();
64	    if (max_len < len)
65	      max_len = len;
66	  }
67	  return max_len;
68	}
